#include <iostream>
#include <vector>
#include <string>
using namespace std;

bool ok(const vector<int>& grid, int pos, int d) {
    for (int j = 0; j < 16; j++) {
        if (j != pos && grid[j] == d) {
            if (j / 4 == pos / 4 || j % 4 == pos % 4 || (j / 8 == pos / 8 && (j % 4) / 2 == (pos % 4) / 2)) return false;
        }
    }
    return true;
}

long long countFill(vector<int>& grid, int pos) {
    if (pos == 16) return 1;
    if (grid[pos] != 0) return ok(grid, pos, grid[pos]) ? countFill(grid, pos + 1) : 0;
    long long total = 0;
    for (int d = 1; d <= 4; d++) {
        if (ok(grid, pos, d)) {
            grid[pos] = d;
            total += countFill(grid, pos + 1);
            grid[pos] = 0;
        }
    }
    return total;
}

int main() {
    vector<string> board(4);
    for (int i = 0; i < 4; i++) {
        cin >> board[i];
